insert into public.recipes (slug, title, description, storage_note, servings, prep_minutes,
  cook_minutes, tags, status, source, source_ref, validated_at)
select v.slug, v.title, v.description, v.storage, v.servings, v.prep, v.cook, v.tags,
  'published', 'curated', 'Aux Petits Oignons — recette originale', now()
from (values
  ('one-pot-pates-thon-tomate', 'One pot de pâtes au thon et à la tomate', 'Des pâtes cuites directement dans la sauce tomate à l''oignon et à l''ail, avec le thon ajouté à la fin et du parmesan. Une seule sauteuse, rien à égoutter.', 'Se garde 2 jours au réfrigérateur.', 2, 5, 15, array['plat', 'poele', 'peu-de-vaisselle', 'economique']::text[]),
  ('one-pot-pates-poulet-poireau', 'One pot de pâtes au poulet, poireau et champignons', 'Des pâtes cuites dans un bouillon léger avec du poulet, du poireau et des champignons, liées au fromage blanc et au parmesan. Crémeux sans crème, et une seule sauteuse.', 'Se garde 2 jours au réfrigérateur.', 2, 10, 15, array['plat', 'poele', 'peu-de-vaisselle']::text[]),
  ('gnocchis-poeles-tomate-mozzarella', 'Gnocchis dorés à la poêle, tomate et mozzarella', 'Des gnocchis dorés à la poêle sans précuisson, nappés de sauce tomate aux herbes, couverts de mozzarella fondue à couvert. Une poêle et c''est tout.', 'À manger tout de suite.', 2, 5, 15, array['plat', 'poele', 'peu-de-vaisselle', 'economique']::text[]),
  ('riz-sauteuse-poulet-crevettes-paprika', 'Riz à la sauteuse au poulet, crevettes et paprika', 'Un riz cuit dans la sauteuse avec du poulet, de l''oignon, de la tomate, du paprika et du curcuma, puis des crevettes ajoutées en fin de cuisson. Façon paella, sans la poêle spéciale.', 'Se garde 1 jour au réfrigérateur ; bien réchauffer.', 2, 10, 25, array['plat', 'poele', 'peu-de-vaisselle', 'monde']::text[]),
  ('shakshuka-pois-chiches-oeufs', 'Shakshuka aux pois chiches et œufs pochés', 'Des œufs pochés dans une sauce tomate épicée au cumin et au paprika, enrichie de pois chiches, servis dans la poêle avec du pain pour saucer.', 'La sauce se garde 3 jours au réfrigérateur ; pocher les œufs au moment de servir.', 2, 5, 20, array['plat', 'poele', 'peu-de-vaisselle', 'economique', 'monde']::text[]),
  ('saumon-poireaux-pommes-de-terre-poele', 'Saumon, poireaux fondus et pommes de terre à la poêle', 'Des pommes de terre en petits dés dorées à couvert, des poireaux fondus et des pavés de saumon posés dessus pour finir, avec un trait de citron. Tout dans la même poêle.', 'Se garde 1 jour au réfrigérateur.', 2, 10, 25, array['plat', 'poele', 'peu-de-vaisselle']::text[]),
  ('risotto-poulet-champignons-sauteuse', 'Risotto au poulet et aux champignons', 'Un risotto crémeux au parmesan, avec du poulet et des champignons saisis dans la même sauteuse. On remue, et c''est à peu près tout.', 'Se garde 1 jour au réfrigérateur ; réchauffer avec un peu d''eau.', 2, 10, 25, array['plat', 'poele', 'peu-de-vaisselle']::text[]),
  ('chili-con-carne-riz-une-cocotte', 'Chili con carne et riz dans la même cocotte', 'Un chili de bœuf aux haricots rouges, cumin et paprika, dans lequel on fait cuire le riz directement. Un plat complet, une seule cocotte à laver.', 'Se garde 3 jours au réfrigérateur ou 2 mois au congélateur.', 2, 10, 30, array['plat', 'peu-de-vaisselle', 'economique', 'monde']::text[]),
  ('dahl-lentilles-corail-carottes-coco', 'Dahl de lentilles corail aux carottes et coco', 'Des lentilles corail mijotées dans un faitout avec des carottes, de la tomate, du curry et du lait de coco, jusqu''à devenir fondantes, servies avec du pain et du yaourt.', 'Se garde 3 jours au réfrigérateur ou 2 mois au congélateur.', 2, 10, 25, array['plat', 'peu-de-vaisselle', 'economique', 'monde']::text[]),
  ('tajine-poulet-carottes-pois-chiches', 'Tajine de poulet aux carottes et pois chiches', 'Du poulet mijoté au cumin et au curcuma avec des carottes, des pois chiches, de la tomate et des raisins secs, servi sur une semoule gonflée dans le bouillon de cuisson.', 'Le tajine se garde 3 jours au réfrigérateur ou 2 mois au congélateur.', 2, 15, 30, array['plat', 'peu-de-vaisselle', 'monde']::text[]),
  ('poulet-pommes-de-terre-carottes-un-plat', 'Poulet, pommes de terre et carottes rôtis dans un seul plat', 'Des morceaux de poulet, des pommes de terre, des carottes et de l''oignon rouge rôtis ensemble aux herbes et à l''ail, avec un yaourt citronné. On enfourne et on oublie.', 'Se garde 2 jours au réfrigérateur.', 2, 15, 35, array['plat', 'four', 'peu-de-vaisselle', 'economique']::text[]),
  ('saumon-patate-douce-brocoli-plat', 'Saumon, patate douce et brocoli en un seul plat', 'Des cubes de patate douce rôtis, rejoints par des fleurettes de brocoli et des pavés de saumon à la moutarde et au miel. Tout cuit dans le même plat.', 'Se garde 1 jour au réfrigérateur.', 2, 10, 30, array['plat', 'four', 'peu-de-vaisselle']::text[]),
  ('pois-chiches-rotis-butternut-feta', 'Pois chiches rôtis, butternut et feta', 'De la courge butternut et des pois chiches rôtis au cumin avec de l''oignon rouge, puis de la feta émiettée et une sauce au yaourt. Un seul plat, très peu de préparation.', 'Se garde 2 jours au réfrigérateur.', 2, 10, 35, array['plat', 'four', 'peu-de-vaisselle', 'economique']::text[]),
  ('cabillaud-chapelure-pommes-de-terre-poireau', 'Cabillaud en croûte de chapelure, pommes de terre et poireau', 'Des rondelles de pommes de terre et de poireau rôties en lit, avec du cabillaud couvert d''une croûte de chapelure au parmesan et au citron. Un plat, un dîner.', 'Se garde 1 jour au réfrigérateur.', 2, 15, 35, array['plat', 'four', 'peu-de-vaisselle']::text[]),
  ('tofu-roti-patate-douce-carottes-soja', 'Tofu rôti, patate douce et carottes au soja-miel', 'Des cubes de tofu, de patate douce et de carotte rôtis dans un plat avec une sauce soja, miel et gingembre qui caramélise, parsemés de sésame.', 'Se garde 2 jours au réfrigérateur.', 2, 10, 30, array['plat', 'four', 'peu-de-vaisselle', 'monde']::text[]),
  ('clafoutis-sale-poireau-thon', 'Clafoutis salé au poireau et au thon', 'Un appareil aux œufs et au lait versé sur du poireau émincé cru et du thon, avec un peu d''emmental, puis doré au four. Une salade à côté, et un seul plat à laver.', 'Se garde 2 jours au réfrigérateur ; se mange aussi froid.', 2, 15, 35, array['plat', 'four', 'peu-de-vaisselle', 'economique']::text[]),
  ('patates-douces-micro-ondes-haricots-cheddar', 'Patates douces farcies au micro-ondes, haricots rouges et cheddar', 'Des patates douces attendries au micro-ondes, ouvertes et garnies de haricots rouges au cumin, de cheddar fondu et de yaourt. Aucune casserole.', 'La garniture se garde 3 jours au réfrigérateur.', 2, 5, 12, array['plat', 'peu-de-vaisselle', 'economique', 'monde']::text[]),
  ('bol-semoule-micro-ondes-thon-betterave', 'Bol de semoule au micro-ondes, thon et betterave', 'Une semoule gonflée au micro-ondes, mélangée à du thon, de la betterave, des carottes râpées et de l''oignon rouge, avec une vinaigrette au citron. Un bol et une fourchette.', 'Se garde 2 jours au réfrigérateur ; se mange froid.', 2, 10, 3, array['plat', 'peu-de-vaisselle', 'economique']::text[]),
  ('saumon-micro-ondes-poireau-pommes-de-terre', 'Saumon au micro-ondes, poireau et pommes de terre', 'Des pommes de terre et du poireau attendris au micro-ondes dans un plat couvert, puis du saumon posé dessus avec du citron et un fromage blanc à la ciboulette. Rapide et sans odeur de friture.', 'Se garde 1 jour au réfrigérateur.', 2, 10, 14, array['plat', 'peu-de-vaisselle']::text[]),
  ('oeufs-brouilles-micro-ondes-champignons', 'Œufs brouillés au micro-ondes, champignons et tartines', 'Des œufs battus avec des champignons émincés et un peu d''emmental, brouillés au micro-ondes en remuant toutes les 30 secondes, servis sur des tranches de pain avec une salade.', 'À manger tout de suite.', 2, 5, 4, array['plat', 'peu-de-vaisselle', 'economique']::text[])
) as v(slug, title, description, storage, servings, prep, cook, tags);

