  ('oeufs-brouilles-micro-ondes-champignons', 1, 'Émincer finement les champignons et les passer 1 minute au micro-ondes dans un grand bol.'),
  ('oeufs-brouilles-micro-ondes-champignons', 2, 'Ajouter les œufs, le lait, l''emmental, du sel et du poivre, et battre à la fourchette.'),
  ('oeufs-brouilles-micro-ondes-champignons', 3, 'Passer 30 secondes au micro-ondes, remuer, et répéter jusqu''à ce que les œufs soient pris mais encore crémeux.'),
  ('oeufs-brouilles-micro-ondes-champignons', 4, 'Servir sur les tranches de pain avec la ciboulette et la salade assaisonnée au vinaigre et à l''huile.')
) as v(recipe, pos, instruction)
join public.recipes r on r.slug = v.recipe;

-- Garde-fou : une jointure silencieusement vide (slug introuvable) fait échouer la migration.
do $$
begin
  if (select count(*) from public.recipe_ingredients ri join public.recipes r on r.id = ri.recipe_id
      where r.slug in ('one-pot-pates-thon-tomate', 'one-pot-pates-poulet-poireau', 'gnocchis-poeles-tomate-mozzarella', 'riz-sauteuse-poulet-crevettes-paprika', 'shakshuka-pois-chiches-oeufs', 'saumon-poireaux-pommes-de-terre-poele', 'risotto-poulet-champignons-sauteuse', 'chili-con-carne-riz-une-cocotte', 'dahl-lentilles-corail-carottes-coco', 'tajine-poulet-carottes-pois-chiches', 'poulet-pommes-de-terre-carottes-un-plat', 'saumon-patate-douce-brocoli-plat', 'pois-chiches-rotis-butternut-feta', 'cabillaud-chapelure-pommes-de-terre-poireau', 'tofu-roti-patate-douce-carottes-soja', 'clafoutis-sale-poireau-thon', 'patates-douces-micro-ondes-haricots-cheddar', 'bol-semoule-micro-ondes-thon-betterave', 'saumon-micro-ondes-poireau-pommes-de-terre', 'oeufs-brouilles-micro-ondes-champignons')) <> 205 then
    raise exception 'Lignes d''ingrédients manquantes dans le seizième lot de recettes.';
  end if;
end;
$$;
